class CustomerRepository:
    def __init__(self, session):
        self.session = session
        self.deleted = 0

    def _statement(self):
        return text('DELETE FROM customers WHERE id = :customer_id')

    def _execute(self, customer_id):
        result = self.session.execute(self._statement(), {'customer_id': customer_id})
        self.deleted += result.rowcount
        return result.rowcount

    def remove(self, customer_id):
        removed = self._execute(customer_id)
        self.session.commit()
        return removed

    def remove_many(self, customer_ids):
        total = 0
        for customer_id in customer_ids:
            total += self.remove(customer_id)
        return total

